window.__ModuleLoader__.load({
  id: 'dsh-student-notebook',
  factory(require) {
    /**
     * Student-Notebook theme stylesheet.
     *
     * `client.js` is generated by `node build.mjs`; edit `src/theme.css` and
     * rebuild instead of editing the generated file.
     */
    const THEME_CSS = __THEME_CSS_JSON__;

    const STYLE_ID = 'dsh-student-notebook/student-notebook.css';
    const STYLE_SELECTOR = `style[data-plugin-css="${STYLE_ID}"]`;

    function mount() {
      document.documentElement.setAttribute('data-student-notebook', 'on');

      let style = document.querySelector(STYLE_SELECTOR);
      if (!style) {
        style = document.createElement('style');
        style.dataset.plugin = 'dsh-student-notebook';
        style.dataset.pluginCss = STYLE_ID;
        style.dataset.studentNotebook = 'true';
      }

      // The theme must win against the Harness's own token/theme styles. Plugin
      // bundles can load early (before the UI theme injects its <style> tags),
      // and equal-specificity rules then lose on source order. A <style> element
      // placed in <body> comes after every <head> stylesheet in tree order, so
      // it wins without !important and keeps the theme easy to override.
      style.textContent = THEME_CSS;
      if (!style.isConnected) {
        (document.body || document.head).appendChild(style);
      }

      let disposed = false;
      const moveToBody = () => {
        if (disposed || !document.body || style.parentNode === document.body) return;
        document.body.appendChild(style);
      };

      if (document.body) {
        moveToBody();
      } else if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', moveToBody, { once: true });
      } else {
        requestAnimationFrame(moveToBody);
      }

      return () => {
        disposed = true;
        style.remove();
        document.documentElement.removeAttribute('data-student-notebook');
      };
    }

    function apply(ctx) {
      if (typeof document === 'undefined') return;

      if (ctx && typeof ctx.effect === 'function') {
        ctx.effect(mount, 'dsh-student-notebook: paper stylesheet');
        return;
      }

      mount();
    }

    return { apply };
  },
});
